def shared_manager(chart, a, b):
    def find(node):
        if node is None:
            return None
        name, left, right = node
        if name == a or name == b:
            return name
        from_left, from_right = find(left), find(right)
        if from_left is not None and from_right is not None:
            return name
        return from_left if from_left is not None else from_right

    return find(chart)
